using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — demonstrates EF Core 9 breaking changes for the
// Cosmos provider:
//
// 1. Discriminator property renamed: EF Core 9 now uses "$type" instead of
//    "Discriminator". For existing documents that already store "Discriminator",
//    you must explicitly configure the old name to avoid data incompatibility.
//
// 2. Synchronous I/O removed: Cosmos provider no longer supports sync APIs
//    (e.g., .ToList(), .First()). All queries must use async equivalents
//    (.ToListAsync(), .FirstAsync(), etc.).

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change fix #1: EF Core 9 defaults the discriminator property
        // name to "$type". Existing documents use "Discriminator", so we must
        // preserve backward compatibility explicitly.
        modelBuilder.Entity<Product>()
            .ToContainer("Products")
            .HasDiscriminant("Discriminator")   // keep legacy property name
            .HasValue<Product>("Product");

        modelBuilder.Entity<Product>()
            .HasPartitionKey(p => p.Category);
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
    public decimal Price { get; set; }
}

// Breaking change fix #2: Synchronous Cosmos queries are no longer supported.
// Before (EF Core 8):
//   var items = db.Products.Where(p => p.Price > 10).ToList();
// After (EF Core 9) — must use async:
class ProductService
{
    private readonly CosmosDbContext _db;
    public ProductService(CosmosDbContext db) => _db = db;

    // ✅ Correct — async query
    public async Task<List<Product>> GetExpensiveProductsAsync()
    {
        return await _db.Products
            .Where(p => p.Price > 10)
            .ToListAsync();
    }

    // ✅ Correct — async single item
    public async Task<Product?> GetByIdAsync(string id)
    {
        return await _db.Products
            .FirstOrDefaultAsync(p => p.Id == id);
    }
}

